#include <iostream>
using namespace std;

class Engine {
public:
    void start() const { cout << "Engine starts" << endl; }
};

class Car {
    Engine engine_;

public:
    void drive() const {
        engine_.start();
        cout << "Car moves" << endl;
    }
};

int main() {
    Car c;
    c.drive();
    return 0;
}

#include <iostream>
using namespace std;

class Animal {
public:
    virtual void speak() const { cout << "..." << endl; }
};

class Dog : public Animal {
public:
    void speak() const override { cout << "Woof" << endl; }
};

void by_value(Animal a) { a.speak(); }
void by_ref(const Animal& a) { a.speak(); }

int main() {
    Dog d;
    by_value(d);
    by_ref(d);
    return 0;
}

